// ============================================================================
// Bluetooth5_apb: APB4 register wrapper around Bluetooth5_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/Bluetooth5.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/Bluetooth5.md
// ============================================================================
module Bluetooth5_apb #(
  parameter int ADV_INTV = 1200
) (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq,
  input logic rxd,
  output logic txd,
  output logic tx_act
);
  localparam logic [31:0] ID_VALUE = 32'h42540200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [23:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd24) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & (~|hit | (PWRITE & (PSTRB != 4'hF) & (hit[5] | hit[6] | hit[7] | hit[8] | hit[9] | hit[10] | hit[11] | hit[12] | hit[13] | hit[14] | hit[15] | hit[16] | hit[17] | hit[18] | hit[19] | hit[20] | hit[21] | hit[22])));   // core registers take whole words

  // ---------------- core ----------------
  logic          c_tx_act;
  logic          c_cfg_we;
  logic [7:0]    c_cfg_wdata;
  logic          c_irq;
  Bluetooth5_top #(.ADV_INTV(ADV_INTV)) u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .rxd(rxd),
    .txd(txd),
    .tx_act(c_tx_act),
    .cfg_we(c_cfg_we),
    .cfg_addr((wr ? ((hit[5] ? 5'd0 : 5'd0) | (hit[6] ? 5'd1 : 5'd0) | (hit[7] ? 5'd2 : 5'd0) | (hit[8] ? 5'd3 : 5'd0) | (hit[9] ? 5'd4 : 5'd0) | (hit[10] ? 5'd5 : 5'd0) | (hit[11] ? 5'd6 : 5'd0) | (hit[12] ? 5'd7 : 5'd0) | (hit[13] ? 5'd8 : 5'd0) | (hit[14] ? 5'd9 : 5'd0) | (hit[15] ? 5'd10 : 5'd0) | (hit[16] ? 5'd11 : 5'd0) | (hit[17] ? 5'd12 : 5'd0) | (hit[18] ? 5'd13 : 5'd0) | (hit[19] ? 5'd14 : 5'd0) | (hit[20] ? 5'd15 : 5'd0) | (hit[21] ? 5'd16 : 5'd0) | (hit[22] ? 5'd17 : 5'd0)) : 5'd0)),
    .cfg_wdata(c_cfg_wdata),
    .irq(c_irq)
  );
  assign tx_act = c_tx_act;  // also readable in the registers

  // ---------------- registers ----------------
  logic [0:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[0:0] & wmask[0:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
    end
  end

  // ---------------- core inputs ----------------
  // CFG: the core's register port (indices on the instance)
  assign c_cfg_we = wr & (PSTRB == 4'hF) & (hit[5] | hit[6] | hit[7] | hit[8] | hit[9] | hit[10] | hit[11] | hit[12] | hit[13] | hit[14] | hit[15] | hit[16] | hit[17] | hit[18] | hit[19] | hit[20] | hit[21] | hit[22]);
  assign c_cfg_wdata = PWDATA[7:0];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd23: apb_rdata = 32'({c_tx_act});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
